"""Opt-in seam-only welding of already validated network surface providers.

The network tags each interior vertex with (kind+1, owner, local index), an
identity unique to that provider. Only keys (0, mouth, rank) have multiple
copies across providers. Selecting exactly those copies for Merge by Distance
avoids processing unrelated interiors. The complete physical-agreement,
expected-count, orientation, cell, ownership and separator checks remain.

This factory copies affected assembly groups and their parents. It does not
alter the supplied tree, source objects or independently evaluated providers.
It is an experiment until full-network, failure and timing qualification pass.
"""
import hashlib


def build(root):
    memo = {}
    changed = []

    def clone(tree):
        pointer = tree.as_pointer()
        if pointer in memo:return memo[pointer]
        # The labels below occur in other constructors too. Only the network's
        # complete/partial assembly owns the (kind, owner, index) key contract.
        family = tree.name.startswith((
            'Prochitecture Streets / Connected curved physical surfaces v',
            'Prochitecture Streets / Original local failure assembly candidate v'))
        target = family and any(n.bl_idname == 'GeometryNodeMergeByDistance'
                                and n.label == 'Weld exact integer identities only' for n in tree.nodes)
        children = {n.name: clone(n.node_tree) for n in tree.nodes
                    if n.type == 'GROUP' and n.node_tree}
        changes = any(children[n.name] != n.node_tree for n in tree.nodes
                      if n.name in children)
        if not target and not changes:
            memo[pointer] = tree
            return tree
        result = tree.copy()
        result.name = 'Prochitecture Streets / Selected network seams v1 / '+hashlib.sha256(
            tree.name.encode()).hexdigest()[:16]
        memo[pointer] = result
        for name, child in children.items():
            # Copies retain all interface identifiers; no interface is rebuilt.
            if result.nodes[name].node_tree != child:result.nodes[name].node_tree = child
        if target:
            merge, = [n for n in result.nodes if n.bl_idname == 'GeometryNodeMergeByDistance'
                      and n.label == 'Weld exact integer identities only']
            assert not merge.inputs['Selection'].is_linked
            assert merge.inputs['Selection'].default_value
            position, = [link.from_node for link in merge.inputs['Geometry'].links]
            assert position.bl_idname == 'GeometryNodeSetPosition'
            key, = [link.from_node for link in position.inputs['Position'].links]
            assert key.bl_idname == 'GeometryNodeInputNamedAttribute'
            assert key.inputs['Name'].default_value == '_bridge_key'
            separate = result.nodes.new('ShaderNodeSeparateXYZ')
            result.links.new(key.outputs['Attribute'], separate.inputs['Vector'])
            compare = result.nodes.new('FunctionNodeCompare')
            compare.data_type = 'FLOAT'; compare.operation = 'EQUAL'
            compare.inputs['B'].default_value = 0.
            compare.inputs['Epsilon'].default_value = 0.
            result.links.new(separate.outputs['X'], compare.inputs['A'])
            result.links.new(compare.outputs['Result'], merge.inputs['Selection'])
            merge.label = 'Weld only declared matching network mouth identities'
            result['st_network_seam_weld'] = 1
            changed.append(tree.name)
        return result

    result = clone(root)
    if not changed:raise ValueError('No original network assembly weld found')
    result['st_network_seam_weld_sources'] = changed
    return result
